scripts:
// 赛博朋克 2077 义体玩法(scripts 函数式扩展示例:未来 DLC 需要系统/命令时的写法)
// 义体状态 = pawn.extra.cyber(单包自洽键,写读同包,存档扩展点随档;不入契约表)
// 命令:把斯安威斯坦装到选中/指定小人身上(与 draft 命令同 ctx/pawnStates 契约)
m.registerCommand('dlc:install-cyber', (ctx, cmd) => {
  const eids = cmd.pawnId !== undefined ? [cmd.pawnId] : ctx.selected;
  for (const eid of eids) {
    const st = ctx.pawnStates.get(eid);
    if (!st) continue;
    st.extra = Object.assign({}, st.extra, { cyber: 'dlc:sandevistan' });
    ctx.logEvent('🦾 义体医生为 #' + eid + ' 植入斯安威斯坦(神经反应加速)');
  }
});
// 义体系统:装配进 production 组(craft 之前,表外系统 before 锚点;
// 每 60s 义体携带者触发神经加速叙事,占位效果)
m.registerSystemDef({
  id: 'dlc:cyber',
  label: '义体改造',
  category: 'production',
  before: 'craft',
  ctor: (sim) => {
    let acc = 0;
    return {
      id: 'dlc:cyber',
      update(dt) {
        acc += dt;
        if (acc < 60) return;
        acc = 0;
        for (const [eid, st] of sim.pawnStates) {
          if (st.extra && st.extra.cyber) {
            sim.logEvent('⚡ #' + eid + ' 的斯安威斯坦闪过一道银光(神经反应加速)');
          }
        }
      },
    };
  },
});
